$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue'
$Stage='D:\Claude\swiftright\.factory-work\hosts\stack-overlay-colors';$Requests=Join-Path $Stage 'requests-final-r1'
if(@(Get-Process swift,swiftc,swift-build,clang,FactoryProbe -ErrorAction SilentlyContinue).Count){throw 'compiler/native lane busy'}
if(Test-Path -LiteralPath $Requests){throw 'fresh final requests required'}
New-Item -ItemType Directory -Path $Requests|Out-Null
$Rows='[{"path":"plan-prebuild-v4.json","bytes":9112,"sha256":"a798eba6d348d3d75efddb4eecd1198e01105f1afc9eae2f376ca0cf18c5c59a","base64":""},{"path":"build-owned-pilot-v1.ps1","bytes":11193,"sha256":"37aeeb7803eacf89f7ded1457099d49259ce0670adf6f8aa1a42357b8f8aea2c","base64":""},{"path":"plan-final-v4.json","bytes":26528,"sha256":"74d4c85d8381a9789d999ddb2bcc614c7e417f42e97330bc4e1bb3c4cf31f21e","base64":""},{"path":"build-owned-final-v1.ps1","bytes":11188,"sha256":"eb43556ce42b2a98bf0a0829746940d9dd707e1bd84dc3bd9265f5cd74b8b506","base64":""},{"path":"final-remote-entry.ps1","bytes":3088,"sha256":"d3ce32b0e65fa79e1f9f29e9b5c1a8b7068d1d8ab5371de8866312f010da79dc","base64":""}]'|ConvertFrom-Json
foreach($Row in @($Rows)){
  $P=Join-Path $Requests $Row.path
  [IO.File]::WriteAllBytes($P,[Convert]::FromBase64String($Row.base64))
  $I=Get-Item -LiteralPath $P
  if($I.Length -ne $Row.bytes -or (Get-FileHash -LiteralPath $P).Hash.ToLowerInvariant() -cne $Row.sha256){throw 'staged finalized source drift'}
}
& (Join-Path $Requests 'final-remote-entry.ps1') -PreflightOnly
& (Join-Path $Requests 'final-remote-entry.ps1')
